      SUBROUTINE INDUCTC---- MOVE ELEMENTS TO FRONT OF DATA ARRAY, INSERTING OR REMOVINGC---- AS SPECIFIEDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'LABELI.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDCARD.CIN'            INCLUDE 'RDWRDS.CIN'      INCLUDE 'ICOPY.CIN'C-----------------------------------------------------------------------C      IIOLD = 0      NUMMAX = NELLIM       IF (NUM .GE. NELLIM + 1) GO TO 500   50 II = ISTOR(NUM)      NTYPE = IABS(IDATA(II))      LABLE = LABEL(NUM)      IF (LABLE .EQ. LABELI) THEN        IF (REMOVE) GO TO 200        IF (INSERT) THEN          IF (BEFI) THEN            GO TO 500          ELSE            NUMMAX = NUM - 2          ENDIF        ENDIF      ENDIFCC     CHANGE REFERENCES TO PHYSICAL PARAMETERSC      NPARMS = 0      IF (II .LT. IIOLD) GO TO 130      CALL SKETCH(NUM)      NEL = NEL + 1      NP1 = NPARMS + 1      IIPN = II + NPARMS      IF (I100 .EQ. 0 .OR. I100 .GT. IIPN) GO TO 100      DO 70 J = 1, NP1      IAD = II + J      IF (IAD .EQ. I100) THEN        IANEW = ISTOR(NEL) + J        CALL FIXREF        CALL FND100        IF (I100 .GT. IIPN) GO TO 100      ENDIF   70 CONTINUECC     COPY ELEMENT TO LIST AT BEGINNING OF DATA ARRAYC  100 DO 120 J = 1, NP1      I1 = II + J - 1      ICOPY = I1      DATA(I) = DATA(I1)      TIE(I) = TIE(I1)      I = I + 1  120 CONTINUE      IF (.NOT. FLUSHL) ISTOR(NEL+1) = I      IIOLD = MAX0(II,IIOLD)      GO TO 180C  130 NNN = 0      IF (NEL .EQ. 0) GO TO 180      DO 140 NN = 1, NEL      NNN = NN      IF (LABEL(NN) .EQ. LABLE) GO TO 150  140 CONTINUE      GO TO 160  150 ISTOR(NEL) = ISTOR(NNN)  160 IF (.NOT. FLUSHL) ISTOR(NEL+1) = IC  180 NDESCR(NEL) = NDESCR(NUM)      LABEL(NEL) = LABLEC  200 NUM = NUM + 1      IF (NUM .LE. NUMMAX) GO TO 50C  500 CONTINUE      RETURN      END